void procesar_linea(const std::string& linea, int numero, std::vector<Admision>& admitidos) {
    Registro candidata;
    const Resultado local = leer_registro(linea, candidata);

    if (local != Resultado::aceptado) {
        std::cout << "R " << numero << ' ' << nombre(local) << '\n';
        return;
    }
